SELECT id, customer_id, plan, start_date, end_date, monthly_fee, status, MIN(monthly_fee) OVER w_grp AS customer_id_min_monthly_fee, PERCENT_RANK() OVER (ORDER BY monthly_fee DESC NULLS FIRST) AS monthly_fee_percent_rank, SUM(monthly_fee) OVER (PARTITION BY status, customer_id ORDER BY end_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_monthly_fee FROM subscriptions WINDOW w_grp AS (PARTITION BY customer_id);
